:root {
  --bg-card: #2a1a2e;
  --bg-header: #3d1f3f;
  --bg-footer: #1e1220;
  --accent-gold: #c9a84c;
  --accent-rose: #d4507a;
  --text-primary: #f2ead8;
  --text-muted: #a89080;
  --dot-1: #8b1a3a;
  --dot-2: #c0392b;
  --dot-3: #7d3068;
  --dot-4: #4a2060;
  --fill-1: #8b1a3a;
  --fill-2: #c0392b;
  --fill-3: #7d3068;
  --fill-4: #4a2060;
  --bar-bg: #3d2840;
  --border-color: #5a3060;
  --tag-bg: #3a2040;
}

.flight-card {
  width: 500px;
  background-color: var(--bg-card);
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid var(--border-color);
  margin: 0 auto;
}

.card-header {
  background-color: var(--bg-header);
  padding: 18px 24px 16px;
  border-bottom: 1px solid var(--border-color);
}

.label {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent-gold);
  background-color: var(--bg-card);
  border: 1px solid var(--accent-gold);
  border-radius: 20px;
  padding: 3px 10px;
  margin-bottom: 8px;
}

.title {
  font-size: 26px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0 0 4px;
  line-height: 1.1;
}

.subtitle {
  font-size: 12px;
  color: var(--text-muted);
  margin: 0;
}

.wines {
  padding: 12px 24px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.wine-item {
  display: flex;
  align-items: center;
  gap: 12px;
  background-color: var(--tag-bg);
  border-radius: 10px;
  padding: 10px 14px;
  border: 1px solid var(--border-color);
}

.pour-dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
}

.dot-1 { background-color: var(--dot-1); }
.dot-2 { background-color: var(--dot-2); }
.dot-3 { background-color: var(--dot-3); }
.dot-4 { background-color: var(--dot-4); }

.wine-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 0 0 160px;
}

.wine-name {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
  line-height: 1.2;
}

.wine-origin {
  font-size: 11px;
  color: var(--text-muted);
}

.tasting-bar {
  flex: 1;
  height: 6px;
  background-color: var(--bar-bg);
  border-radius: 999px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 999px;
}

.fill-1 { width: 85%; background-color: var(--fill-1); }
.fill-2 { width: 60%; background-color: var(--fill-2); }
.fill-3 { width: 72%; background-color: var(--fill-3); }
.fill-4 { width: 78%; background-color: var(--fill-4); }

.wine-note {
  font-size: 11px;
  font-weight: 600;
  color: var(--accent-gold);
  flex: 0 0 36px;
  text-align: right;
}

.card-footer {
  background-color: var(--bg-footer);
  padding: 12px 24px;
  display: flex;
  gap: 0;
  border-top: 1px solid var(--border-color);
}

.footer-tag {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
  padding: 0 12px;
  border-right: 1px solid var(--border-color);
}

.footer-tag:first-child {
  padding-left: 0;
}

.footer-tag:last-child {
  border-right: none;
}

.tag-label {
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--text-muted);
}

.tag-value {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-gold);
}
